-- handwritten: runtime/client/mixins/Object.lua

do

local CreateObject, CreateObjectNoOffset, IsModelInCdimage = CreateObject, CreateObjectNoOffset, IsModelInCdimage
local SetEntityHeading = SetEntityHeading
local CreateWeaponObject, IsWeaponValid = CreateWeaponObject, IsWeaponValid
local RequestWeaponAsset, HasWeaponAssetLoaded = RequestWeaponAsset, HasWeaponAssetLoaded

---@param model fx.Model|integer|string
---@param position vector3|vector4
---@param heading? number
---@param options? fx.ObjectCreateOptions
---@return fx.Object?
statics.createRaw = function(model, position, heading, options)
  local hash = rt.hash(model)
  if not rt.requireLoaded("Object.createRaw", hash, model) then return nil end
  local net = not (options and options.networked == false)
  local mission = not (options and options.missionEntity == false)
  local door = options and options.doorFlag or false
  local create = (options and options.noOffset) and CreateObjectNoOffset or CreateObject
  local h = create(hash, position.x, position.y, position.z, net, mission, door)
  local o = T.wrap(h)
  if o then
    if net then rt.netIntent[o] = true end
    local hd = rt.heading(position, heading)
    if hd ~= 0.0 then SetEntityHeading(h, hd) end
  end
  return o
end

statics.createAsync = rt.makeCreate("Object.createAsync", function(hash)
  return IsModelInCdimage(hash)
end, statics.createRaw)

-- CREATE_WEAPON_OBJECT needs the weapon asset. REQUEST_WEAPON_ASSET(hash, 31, 0): 31 = every anim resource
-- (Base|Cover|Melee|Motion|Stealth), 0 = no extra component, the values the game scripts use.
---@param hash integer
---@return boolean
local function weaponLoaded(hash) return HasWeaponAssetLoaded(hash) end
---@param weapon integer|string
---@param position vector3|vector4
---@param heading? number
---@param options? fx.WeaponObjectCreateOptions
---@return fx.Object?
statics.createWeaponRaw = function(weapon, position, heading, options)
  local hash = rt.hash(weapon)
  if not rt.requireLoaded("Object.createWeaponRaw", hash, weapon, weaponLoaded) then return nil end
  local h = CreateWeaponObject(hash, options and options.ammo or 0, position.x, position.y, position.z,
    not (options and options.defaultComponents == false), (options and options.scale or 1.0) + 0.0, rt.hash(options and options.customModel or 0))
  local o = T.wrap(h)
  if o then
    local hd = rt.heading(position, heading)
    if hd ~= 0.0 then SetEntityHeading(h, hd) end
  end
  return o
end

statics.createWeaponAsync = rt.makeCreate("Object.createWeaponAsync", function(hash) return IsWeaponValid(hash) end,
  statics.createWeaponRaw,
  function(label, hash, timeout)
    return rt.load(label, "weapon", function(h) RequestWeaponAsset(h, 31, 0) end, weaponLoaded, nil, timeout, hash)
  end)

end

return rt.finalize(T)
